const crypto = require("crypto");

const PATH = "/webhook/loan-notification";
const MAX_SKEW_SECONDS = 300;

// One entry per loan status Convex sends; anything else is a bad request.
const TEMPLATES = {
  pending: (tool) => [`New request for your ${tool}`, `Someone asked to borrow your ${tool}. Open LendLoop to approve or decline the request.`],
  approved: (tool) => [`Your request for ${tool} was approved`, `Your request to borrow ${tool} was approved.`],
  declined: (tool) => [`Your request for ${tool} was declined`, `Your request to borrow ${tool} was declined.`],
  cancelled: (tool) => [`Your request for ${tool} was cancelled`, `Your request to borrow ${tool} was cancelled because the tool is no longer listed.`],
  returned: (tool) => [`Return of ${tool} confirmed`, `The owner confirmed that ${tool} was returned. Thanks for borrowing on LendLoop.`],
};

const headers = $input.first().json.headers;
const body = (await this.helpers.getBinaryDataBuffer(0, "data")).toString("utf8");

function isSigned() {
  const secret = $env.N8N_HMAC_SECRET;
  const ts = headers["x-lendloop-timestamp"];
  const signature = headers["x-lendloop-signature"];
  if (!secret || !/^\d+$/.test(ts ?? "") || !/^sha256=[0-9a-f]{64}$/.test(signature ?? "")) return false;
  if (Math.abs(Date.now() / 1000 - Number(ts)) > MAX_SKEW_SECONDS) return false;
  const expected = crypto.createHmac("sha256", secret).update(`${ts}\nPOST\n${PATH}\n${body}`).digest();
  return crypto.timingSafeEqual(Buffer.from(signature.slice(7), "hex"), expected);
}

if (!isSigned()) return [{ json: { outcome: "unauthorized" } }];

let event;
try {
  event = JSON.parse(body);
} catch {
  return [{ json: { outcome: "bad_request" } }];
}
const template = TEMPLATES[event?.status];
const to = event?.recipient?.email;
const tool = event?.tool?.name;
if (!template || typeof to !== "string" || typeof tool !== "string") return [{ json: { outcome: "bad_request" } }];

const [subject, line] = template(tool);
const greeting = event.recipient.name ? `Hi ${event.recipient.name},` : "Hi,";
const text = `${greeting}\n\n${line}\n\nDates: ${event.startDate} to ${event.endDate}.\n\nLendLoop`;
return [{ json: { outcome: "send", to, subject, text } }];
